+  assert.deepEqual(result.items.map((i) => i.label), ["Alpha", "Ångström", "Beta"]);
+});
+
+test("resolve returns results in request order, including duplicates and missing values", async () => {
+  const customers = [makeCustomer(uuid(1), "Alpha"), makeCustomer(uuid(2), "Beta")];
+  const application = makeApplication({ customers });
+  const missing = uuid(999);
+  const result = await dataSource.resolve(
+    { values: [uuid(2), missing, uuid(1), uuid(2)], context: context() },
+    application,
+  );
+  assert.equal(result.results.length, 4);
+  assert.equal(result.results[0].value, uuid(2));
+  assert.equal(result.results[0].item.label, "Beta");
+  assert.equal(result.results[1].value, missing);
+  assert.equal(result.results[1].item, null);
+  assert.equal(result.results[2].item.label, "Alpha");
+  assert.equal(result.results[3].item.label, "Beta");
+});
+
+test("resolve rejects more than 25 requested values and non-UUID values", async () => {
+  const application = makeApplication({ customers: [] });
+  await assert.rejects(() => dataSource.resolve(
+    { values: Array.from({ length: 26 }, () => uuid(1)), context: context() },
+    application,
+  ));
+  await assert.rejects(() => dataSource.resolve(
+    { values: ["not-a-uuid"], context: context() },
+    application,
+  ));
+  assert.equal(application.calls.authorize.length, 0);
+});
+
+test("invalid or unknown request and context input is rejected before authorization", async () => {
+  const application = makeApplication({ customers: [] });
+  const cases = [
+    () => dataSource.query({ search: 42, limit: 1, context: context() }, application),
+    () => dataSource.query({ predicate: "1=1", limit: 1, context: context() }, application),
+    () => dataSource.query({ limit: 1, context: { ...context(), tenant: "tenant-blue" } }, application),
+    () => dataSource.query({ limit: 1, context: { actor: { id: "a" }, target: { id: "b" } } }, application),
+    () => dataSource.resolve({ values: [uuid(1)], extra: true, context: context() }, application),
+  ];
+  for (const invoke of cases) {
+    await assert.rejects(invoke);
+  }
+  assert.equal(application.calls.authorize.length, 0);
+});
+
+test("application authorization denial precedes any record access", async () => {
+  const application = makeApplication({ customers: [makeCustomer(uuid(1), "Alpha")], deny: true });
+  await assert.rejects(() => dataSource.query({ limit: 1, context: context() }, application));
+  assert.equal(application.calls.reads, 0);
+  await assert.rejects(() => dataSource.resolve({ values: [uuid(1)], context: context() }, application));
+  assert.equal(application.calls.reads, 0);
+});
+
+test("private secret field is never exposed in query or resolve output", async () => {
+  const secret = "TOP-SECRET-VALUE";
+  const customers = [{ id: uuid(1), tenantId: TENANT_BLUE, name: "Alpha", secret }];
+  const application = makeApplication({ customers });
+  const queried = await dataSource.query({ limit: 25, context: context() }, application);
+  assert.ok(!JSON.stringify(queried).includes(secret));
+  const resolved = await dataSource.resolve({ values: [uuid(1)], context: context() }, application);
+  assert.ok(!JSON.stringify(resolved).includes(secret));
+});
+
+test("untrusted application rows with invalid ids or labels are dropped", async () => {
+  const customers = [
+    { id: "not-a-uuid", tenantId: TENANT_BLUE, name: "Bad Id", secret: "s" },
+    { id: uuid(1), tenantId: TENANT_BLUE, name: "", secret: "s" },
+    { id: uuid(2), tenantId: TENANT_BLUE, name: "x".repeat(257), secret: "s" },
+    { id: uuid(3), tenantId: TENANT_BLUE, name: "Valid Co", secret: "s" },
+  ];
+  const application = makeApplication({ customers });
+  const result = await dataSource.query({ limit: 25, context: context() }, application);
+  assert.equal(result.items.length, 1);
+  assert.equal(result.items[0].value, uuid(3));
 });
